N = int(data[0])
sizes = list(map(int, data[1:]))

alice_pie = 0
bob_pie = 0

for i in range(N):
    if i % 2 == 0:
        if sizes[i] > sizes[-1]:
            alice_pie += sizes[i]
        else:
            bob_pie += sizes[i]
    else:
        if sizes[i] > sizes[-1]:
            bob_pie += sizes[i]
        else:
            alice_pie += sizes[i]

print(alice_pie)
print(bob_pie)

